html.head:










[[SEO_MODULE]]
[[FONT_MODULE]]
























//
(function(){
  var t=localStorage.getItem('theme')||(window.matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light');
  document.documentElement.setAttribute('data-bs-theme',t);
})();
//



/*
<Group description="Fundo e Cores Base" selector="body">
  <Variable name="body.background" description="Fundo Geral" type="background" color="#ffffff" default="$(color) none repeat scroll top left" value="$(color) none repeat scroll top left"/>
  <Variable name="main.color" description="Cor Principal" type="color" default="#6366f1" value="#6366f1"/>
  <Variable name="theme.text" description="Cor do Texto" type="color" default="#0f172a" value="#0f172a"/>
  <Variable name="header.bg" description="Fundo do Cabeçalho" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="footer.bg" description="Fundo do Rodapé" type="color" default="#0f172a" value="#0f172a"/>
</Group>
<Group description="Tipografia" selector="body">
  <Variable name="body.font" description="Fonte do Texto" type="font" default="normal normal 16px system-ui,-apple-system,sans-serif" value="normal normal 16px system-ui,-apple-system,sans-serif"/>
</Group>
*/

:root {
  --sl-bg-body:        $(body.background);
  --sl-text-main:      $(theme.text);
  --sl-primary:        $(main.color);
  --sl-card-bg:        #ffffff;
  --sl-footer-bg:      #0f172a;
  --sl-radius-lg:      16px;
  --sl-radius-sm:      8px;
  --sl-transition:     all 0.3s cubic-bezier(0.4,0,0.2,1);
  --sl-btn-radius:     8px;
  --sl-btn-shadow:     0 2px 8px rgba(0,0,0,0.15);
  --sl-font-family:    system-ui,-apple-system,sans-serif;
  --sl-heading-weight: 700;

  /* Aliases para impl.json dos nichos SaaS */
  --sd-primary:   var(--sl-primary);     /* techwind */
  --sd-bg:        var(--sl-bg-body);     /* techwind */
  --sd-text:      var(--sl-text-main);   /* techwind */
  --nexus-dark:   #0f172a;               /* saas-nexus */
  --nexus-light:  #f8fafc;               /* saas-nexus */
  --nexus-gray:   #64748b;               /* saas-nexus */
  --ac-bg:        #fffdf7;               /* brutalista-appcraft */
  --ac-dark:      #1a1a1a;               /* brutalista-appcraft */
}

[[DYNAMIC_CSS]]

body {
  background-color: var(--sl-bg-body,#fff);
  color: var(--sl-text-main,#0f172a);
  font-family: var(--sl-font-family,system-ui,sans-serif);
  margin:0; padding:0; overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
}
img { max-width:100%; height:auto; display:block; }
a { color:var(--sl-primary); text-decoration:none; transition:var(--sl-transition); }
a:hover { filter:brightness(0.85); }
h1,h2,h3,h4,h5,h6 { font-weight:var(--sl-heading-weight); }

/* ── TOP BAR ─────────────────────────────────────────── */
.saas-top-bar {
  background: var(--sl-primary);
  color: #fff;
  text-align: center;
  padding: 8px 1rem;
  font-size: .82rem;
  font-weight: 600;
  letter-spacing: .02em;
  min-height: 36px;
}
.saas-top-bar a { color: rgba(255,255,255,.9); text-decoration: underline; }
.saas-top-bar:empty { display: none; }

/* ── NAVBAR ─────────────────────────────────────────────*/
.sl-nav {
  position: sticky;
  top: 0;
  z-index: 1030;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,0,0,0.08);
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
}
.saas-nav-brand { font-weight:800; font-size:1.15rem; letter-spacing:-.03em; color:var(--sl-text-main); }
.saas-nav-brand:hover { color:var(--sl-primary); filter:none; }
.saas-nav-link {
  color: var(--sl-text-main) !important;
  font-size: .875rem;
  font-weight: 600;
  padding: 6px 12px !important;
  border-radius: var(--sl-radius-sm);
  transition: var(--sl-transition);
}
.saas-nav-link:hover { background: rgba(0,0,0,0.05); color:var(--sl-primary) !important; filter:none; }
.saas-cta-btn {
  background: var(--sl-primary);
  color: #fff !important;
  border-radius: var(--sl-btn-radius);
  padding: 7px 18px !important;
  font-size: .875rem;
  font-weight: 700;
  border: 2px solid var(--sl-primary);
  transition: var(--sl-transition);
}
.saas-cta-btn:hover { background: transparent; color: var(--sl-primary) !important; filter:none; }

/* ── HERO SECTION ─────────────────────────────────────── */
.hero-section {
  padding: 5rem 0 4rem;
  background: var(--sl-bg-body,#fff);
  border-bottom: 1px solid rgba(0,0,0,0.06);
  position: relative;
  overflow: hidden;
}
.hero-section::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 60%;
  height: 200%;
  background: radial-gradient(ellipse, color-mix(in srgb,var(--sl-primary) 8%,transparent) 0%, transparent 70%);
  pointer-events: none;
}
.hero-text-area { display:flex; flex-direction:column; justify-content:center; height:100%; }
.hero-text-area .widget h2.title {
  font-size: clamp(2.2rem,4.5vw,3.5rem);
  font-weight: 800;
  letter-spacing: -.04em;
  line-height: 1.1;
  margin-bottom: 1.25rem;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: color-mix(in srgb,var(--sl-primary) 10%,transparent);
  color: var(--sl-primary);
  border: 1px solid color-mix(in srgb,var(--sl-primary) 25%,transparent);
  padding: 5px 12px;
  border-radius: 50px;
  font-size: .78rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  margin-bottom: 1.25rem;
  width: fit-content;
}
.hero-media-area img {
  border-radius: var(--sl-radius-lg);
  box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25);
  width: 100%;
}

/* ── FEATURE CARDS  (CSS nexus targets #saas-cards .widget) */
.saas-feature-section { padding:5rem 0; background:var(--nexus-light,#f8fafc); }
#saas-cards {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  margin-top: 2.5rem;
}
#saas-cards .widget {
  flex: 1;
  min-width: min(290px,100%);
  background: var(--sl-card-bg);
  border: 1px solid rgba(0,0,0,0.07);
  border-radius: var(--sl-radius-lg);
  padding: 2rem 1.75rem;
  box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05);
  transition: var(--sl-transition);
}
#saas-cards .widget:hover { transform:translateY(-4px); box-shadow:0 12px 24px -6px rgba(0,0,0,0.12); }
#saas-cards .widget h2.title {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: .6rem;
  color: var(--sl-text-main);
}

/* ── PRICING SECTION  (nexus targets .pricing-wrapper + #pricing-cards) */
.pricing-wrapper { padding:5rem 0; background:var(--sl-bg-body,#fff); }
.pricing-wrapper .saas-section-label { color:var(--sl-primary); }
#pricing-cards {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  margin-top: 2.5rem;
  align-items: stretch;
}
#pricing-cards .widget {
  flex: 1;
  min-width: min(280px,100%);
  background: var(--sl-card-bg);
  border: 2px solid rgba(0,0,0,0.08);
  border-radius: var(--sl-radius-lg);
  padding: 2.5rem 2rem;
  text-align: center;
  transition: var(--sl-transition);
}
#pricing-cards .widget:hover { border-color:var(--sl-primary); box-shadow:0 20px 40px -10px color-mix(in srgb,var(--sl-primary) 20%,transparent); }
/* Preço: CSS injeta R$ via ::before e aumenta tamanho (padrão nexus) */
#pricing-cards .widget p:first-of-type {
  font-size: 3.5rem;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--sl-primary);
  line-height: 1.1;
}
#pricing-cards .widget p:first-of-type::before { content: 'R$'; font-size: 1.5rem; vertical-align: top; margin-top: .6rem; display: inline-block; }

/* ── TESTIMONIALS  (nexus targets #testimonials .widget) */
.saas-testimonials-section { padding:5rem 0; background:var(--nexus-light,#f8fafc); }
#testimonials {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  margin-top: 2.5rem;
}
#testimonials .widget {
  flex: 1;
  min-width: min(280px,100%);
  background: var(--sl-card-bg);
  border: 1px solid rgba(0,0,0,0.06);
  border-radius: var(--sl-radius-lg);
  padding: 1.75rem;
  font-style: italic;
  color: var(--nexus-gray,#64748b);
}
#testimonials .widget h2.title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--sl-text-main);
  margin-top: 1rem;
  font-style: normal;
}

/* ── BLOG/RESOURCES SECTION ─────────────────────────── */
.blog-section { padding:5rem 0; background:var(--sl-bg-body,#fff); border-top:1px solid rgba(0,0,0,0.06); }
.saas-section-label {
  font-size: .72rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--sl-primary);
  margin-bottom: .4rem;
}
.saas-section-title {
  font-size: clamp(1.6rem,3vw,2.2rem);
  font-weight: 800;
  letter-spacing: -.03em;
  margin-bottom: 0;
}

/* Post cards (nexus: .post-card / template: .news-card) */
.news-card,.post-card {
  background: var(--sl-card-bg);
  border: 1px solid rgba(0,0,0,0.06);
  border-radius: var(--sl-radius-lg);
  overflow: hidden;
  transition: var(--sl-transition);
  height: 100%;
}
@media (min-width:992px) {
  .news-card:hover,.post-card:hover { transform:translateY(-4px); box-shadow:0 16px 30px -5px rgba(0,0,0,0.1); }
}
.post-card-img,.news-card-img {
  width:100%; aspect-ratio:16/9;
  object-fit:cover; display:block;
  transition: transform .4s ease;
}
.news-card:hover .post-card-img,
.news-card:hover .news-card-img { transform:scale(1.04); }
.post-card p.text-muted {
  display:-webkit-box;
  -webkit-line-clamp:3;
  -webkit-box-orient:vertical;
  overflow:hidden;
}

/* ── SINGLE POST (col-8 + col-4 sidebar) ─────────────── */
.saas-post-meta {
  display:flex; flex-wrap:wrap; gap:.85rem;
  padding:.7rem 0; margin-bottom:1.5rem;
  border-top:1px solid rgba(0,0,0,0.07);
  border-bottom:1px solid rgba(0,0,0,0.07);
  font-size:.85rem; color:#64748b;
}
.saas-post-meta a { color:#64748b; }
.saas-post-meta a:hover { color:var(--sl-primary); filter:none; }
.saas-post-hero { border-radius:var(--sl-radius-lg); overflow:hidden; margin-bottom:1.75rem; }
.saas-post-hero img { width:100%; aspect-ratio:16/9; object-fit:cover; display:block; }
.saas-post-body { font-size:1.05rem; line-height:1.85; }
.saas-post-body h2 { margin-top:2.5rem; padding-bottom:.5rem; border-bottom:2px solid rgba(0,0,0,0.07); }
.saas-post-body h3 { margin-top:1.75rem; }
.saas-post-body p { margin-bottom:1.4rem; }
.saas-post-body a { text-decoration:underline; text-decoration-color:color-mix(in srgb,var(--sl-primary) 50%,transparent); text-underline-offset:3px; }
.saas-post-body iframe,.saas-post-body object,.saas-post-body embed { max-width:100%; }
.saas-post-body blockquote {
  margin:2rem 0; padding:1.5rem 2rem;
  border-left:4px solid var(--sl-primary);
  background:color-mix(in srgb,var(--sl-primary) 5%,transparent);
  border-radius:0 var(--sl-radius-sm) var(--sl-radius-sm) 0;
  font-style:italic; font-size:1.05rem; line-height:1.65;
}
.saas-post-body blockquote p { margin-bottom:0; }
.saas-post-body code {
  background: rgba(0,0,0,0.06);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: .88em;
}
.saas-post-body pre {
  background: #1e293b;
  color: #e2e8f0;
  padding: 1.25rem 1.5rem;
  border-radius: var(--sl-radius-sm);
  overflow-x: auto;
  font-size: .88rem;
  line-height: 1.6;
  margin: 1.5rem 0;
}
.saas-post-body pre code { background:none; padding:0; }

/* Sidebar */
.saas-sidebar-widget {
  background: var(--sl-card-bg);
  border: 1px solid rgba(0,0,0,0.07);
  border-radius: var(--sl-radius-lg);
  padding: 1.25rem;
  margin-bottom: 1.5rem;
}
.saas-sidebar-widget-title {
  font-size: .72rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--sl-primary);
  border-bottom: 1px solid rgba(0,0,0,0.07);
  padding-bottom: .6rem;
  margin-bottom: 1rem;
}
.sl-label-widget ul { padding:0; margin:0; list-style:none; display:flex; flex-wrap:wrap; gap:7px; }
.sl-label-list a {
  display:inline-block; padding:5px 12px;
  background:color-mix(in srgb,var(--sl-primary) 10%,transparent);
  color:var(--sl-primary); border-radius:50px;
  font-size:.78rem; font-weight:700; transition:var(--sl-transition);
}
.sl-label-list a:hover { background:var(--sl-primary); color:#fff; filter:none; }
.sl-label-cloud a {
  display:inline-block; padding:4px 12px;
  border:1px solid var(--sl-primary); color:var(--sl-text-main);
  border-radius:var(--sl-radius-lg); font-size:.85rem; transition:var(--sl-transition);
}
.sl-label-cloud a:hover { background:var(--sl-primary); color:#fff; transform:translateY(-2px); filter:none; }

/* ── SHARE / AUTHOR / RELATED ─────────────────────────── */
.sl-share-buttons a.btn { flex-shrink:0; }
.sl-author-box { border:1px solid rgba(0,0,0,0.07) !important; border-radius:var(--sl-radius-lg); box-shadow:0 4px 6px -1px rgba(0,0,0,0.05); }
.sl-related-posts .news-card,.sl-related-posts .post-card { height:100%; }
.sl-related-posts img { width:100%; aspect-ratio:16/9; object-fit:cover; }

/* ── BUTTONS ──────────────────────────────────────────── */
.btn-primary,.btn-outline-primary { border-radius:var(--sl-btn-radius); box-shadow:var(--sl-btn-shadow); }
.btn-outline-primary { color:var(--sl-primary); border-color:var(--sl-primary); }
.btn-outline-primary:hover,.btn-outline-primary:focus,.btn-outline-primary:active,.btn-outline-primary.active {
  background-color:var(--sl-primary); border-color:var(--sl-primary); color:#fff; filter:none;
}

/* ── FOOTER (nexus: .footer-nexus) ─────────────────────── */
.sl-footer,.footer-nexus { background:var(--sl-footer-bg,#0f172a); color:#94a3b8; }
.sl-footer h6,.footer-nexus .widget h2.title {
  color:#f1f5f9; font-weight:700;
  text-transform:uppercase; letter-spacing:.06em; font-size:.75rem;
  margin-bottom:1rem;
}
.sl-footer a,.footer-nexus a { color:#94a3b8; font-size:.875rem; }
.sl-footer a:hover,.footer-nexus a:hover { color:#f1f5f9; filter:none; }
.sl-footer-divider { border-color:rgba(255,255,255,0.08) !important; }

/* ── DARK MODE ────────────────────────────────────────── */
[data-bs-theme="dark"] body { background-color:#0d1117; color:#e2e8f0; }
[data-bs-theme="dark"] .sl-nav { background:rgba(15,17,24,0.95) !important; border-bottom-color:rgba(255,255,255,0.07); }
[data-bs-theme="dark"] .saas-nav-brand { color:#e2e8f0; }
[data-bs-theme="dark"] .saas-nav-link { color:#cbd5e1 !important; }
[data-bs-theme="dark"] .hero-section { background:#0d1117; border-bottom-color:rgba(255,255,255,0.06); }
[data-bs-theme="dark"] .saas-feature-section,
[data-bs-theme="dark"] .saas-testimonials-section { background:#0d1117; }
[data-bs-theme="dark"] #saas-cards .widget,
[data-bs-theme="dark"] #pricing-cards .widget,
[data-bs-theme="dark"] #testimonials .widget,
[data-bs-theme="dark"] .news-card,.post-card { background:#1e2535; border-color:rgba(255,255,255,0.07); }
[data-bs-theme="dark"] .blog-section { background:#0d1117; border-top-color:rgba(255,255,255,0.06); }
[data-bs-theme="dark"] .pricing-wrapper { background:#0d1117; }
[data-bs-theme="dark"] .saas-post-meta { border-color:rgba(255,255,255,0.07); color:#94a3b8; }
[data-bs-theme="dark"] .saas-post-body h2 { border-bottom-color:rgba(255,255,255,0.08); }
[data-bs-theme="dark"] .saas-sidebar-widget { background:#1e2535; border-color:rgba(255,255,255,0.07); }
[data-bs-theme="dark"] .sl-author-box { border-color:rgba(255,255,255,0.07) !important; background:#1e2535; }
[data-bs-theme="dark"] .saas-post-article { background:#1e2535 !important; }
[data-bs-theme="dark"] [data-bs-theme="dark"] .news-card { background:#1e2535; border-color:rgba(255,255,255,0.06); }

/* ── RESPONSIVE ─────────────────────────────────────────── */
@media (max-width:991.98px) {
  .hero-section { padding:3.5rem 0 3rem; }
  .hero-text-area { margin-bottom:2.5rem; }
  #saas-cards,#pricing-cards,#testimonials { flex-direction:column; }
  #saas-cards .widget,#pricing-cards .widget,#testimonials .widget { min-width:100%; }
}

